reference_solution:
def checkSubarraySum(nums, k):
    seen = {0: -1}
    total = 0
    for i, x in enumerate(nums):
        total = (total + x) % k
        if total in seen:
            if i - seen[total] >= 2:
                return True
        else:
            seen[total] = i
    return False

brute_force_solution:
def checkSubarraySum(nums, k):
    for i in range(len(nums)):
        s = nums[i]
        for j in range(i + 1, len(nums)):
            s += nums[j]
            if s % k == 0:
                return True
    return False

